using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
public static class HistoryProcessTests {
 static void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("PASS "+name);}
 static void Pump(Func<bool> done){var frame=new DispatcherFrame();var clock=Stopwatch.StartNew();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(10)};timer.Tick+=(s,e)=>{if(done()||clock.Elapsed.TotalSeconds>15){timer.Stop();frame.Continue=false;}};timer.Start();Dispatcher.PushFrame(frame);Check(done(),"snapshot async loaded");}
 static IEnumerable<T> Nodes<T>(DependencyObject root) where T:DependencyObject {if(root is T)yield return (T)root;foreach(object item in LogicalTreeHelper.GetChildren(root)){var child=item as DependencyObject;if(child!=null)foreach(var found in Nodes<T>(child))yield return found;}}
 public static int Run(string folder){var localConnection=ConnectionProbe.Run(Storage.LocalServer());Check(localConnection.Success&&!localConnection.Message.Contains("GPU")&&localConnection.Message.Contains("无需 SSH"),"local connection feedback is not GPU telemetry");var invalidConnection=ConnectionProbe.Run(new Server{Host="bad host",User="user"});Check(!invalidConnection.Success&&invalidConnection.Message.StartsWith("连接失败"),"invalid SSH target returns connection failure");Check(!ConnectionProbe.Command.Contains("nvidia")&&!ConnectionProbe.Command.Contains("python")&&!ConnectionProbe.Command.Contains("/proc"),"connection test does not run hardware collectors");Directory.CreateDirectory(folder);var log=new List<string>();var store=new ArchiveStore(Path.Combine(folder,"store-"+Guid.NewGuid().ToString("N"))){Days=365};var server=Storage.DefaultServer();var time=DateTime.UtcNow.AddMinutes(-2);var first=Program.Fixture("eight");first.Processes=new List<GpuProcess>{new GpuProcess{Gpu="0",Pid="111",Name="train-a.py",User="alice",Memory="1234 MiB"},new GpuProcess{Gpu="1",Pid="222",Name="train-b.py",User="bob",Memory="5678 MiB"}};var one=ArchiveRecord.From(first,time,5);first.Processes[0].Pid="MUTATED";first.Processes.Clear();Check(one.Processes.Count==2&&one.Processes[0].Pid=="111","snapshot owns immutable process values");store.Append(server,one);var second=Program.Fixture("eight");second.Processes=new List<GpuProcess>{new GpuProcess{Gpu="0",Pid="333",Name="new-task.py",User="carol",Memory="987 MiB"}};store.Append(server,ArchiveRecord.From(second,time.AddSeconds(5),5));var legacy=ArchiveRecord.From(second,time.AddSeconds(10),5);legacy.Processes=null;store.Append(server,legacy);
 var reopened=new ArchiveStore(store.Root);var data=reopened.Query(server,time.AddSeconds(-1),time.AddSeconds(11),CancellationToken.None);Check(data.Points.Count==3,"disk reopen retains all timestamps");
 Metrics shown=null;var panel=new ArchivePanel(reopened,server,m=>{shown=m;var stack=new StackPanel();foreach(var p in m.Processes)stack.Children.Add(Theme.Text(p.Pid+" "+p.User+" "+p.Name+" "+p.Memory,13,Theme.Ink));return new Border{Child=stack};},()=>"test");panel.SetResult(data);panel.ModuleLayout.IsEditing=true;string[] savedOrder=null;panel.ModuleLayout.OrderChanged+=order=>savedOrder=order;panel.ModuleLayout.Move("process",0);Check(panel.ModuleLayout.Order[0]=="process"&&savedOrder[0]=="process","process can move above GPU hardware");panel.ModuleLayout.IsEditing=false;panel.ModuleLayout.Move("hardware",0);Check(panel.ModuleLayout.Order[0]=="process","view mode cannot accidentally reorder");panel.SetMetric("GPU");panel.Chart.Select(time.Ticks);Pump(()=>!panel.SnapshotLoading&&panel.DisplayedRecord!=null);Check(panel.DisplayedRecord.T==time.Ticks&&shown.Processes.Count==2&&shown.Processes[0].User=="alice"&&shown.Processes[0].Memory=="1234 MiB","chart click shows exact saved PID user memory");
 panel.SelectTime(time.AddSeconds(5).Ticks);Pump(()=>!panel.SnapshotLoading&&panel.DisplayedRecord!=null);Check(shown.Processes.Single().Pid=="333"&&shown.Processes.Single().User=="carol","second timestamp has distinct process");panel.SelectTime(time.Ticks);panel.SelectTime(time.AddSeconds(5).Ticks);Pump(()=>!panel.SnapshotLoading&&panel.DisplayedRecord!=null);Check(panel.DisplayedRecord.T==time.AddSeconds(5).Ticks,"rapid selection latest wins");
 panel.SelectTime(time.Ticks);panel.SetMetric("GPU 1");Pump(()=>!panel.SnapshotLoading&&panel.DisplayedRecord!=null);Check(panel.DisplayedProcessCount==1&&shown.Processes.Single().Pid=="222","single GPU filters saved process rows");Check(!Nodes<Button>(panel).Any(x=>(x.Content as string??"").Contains("结束")),"historical table is read only");panel.SelectTime(time.AddSeconds(10).Ticks);Pump(()=>!panel.SnapshotLoading&&panel.DisplayedRecord!=null);Check(panel.DisplayedProcessCount==0&&Nodes<TextBlock>(panel).Any(x=>x.Text.Contains("未保存进程明细")),"legacy record clearly unavailable");Check(panel.ModuleLayout.Order[0]=="process","timestamp changes preserve customized layout");var configPath=Storage.PathName;try{Storage.PathName=Path.Combine(folder,"layout-settings.xml");var settings=new Settings{HistoryModuleOrder=savedOrder};Storage.Save(settings);var restored=Storage.Load();Check(restored.HistoryModuleOrder.SequenceEqual(savedOrder),"custom order persists to local settings and reloads");var secondPanel=new ArchivePanel(reopened,server,m=>new Border(),()=>"test",restored.HistoryModuleOrder);Check(secondPanel.ModuleLayout.Order.SequenceEqual(savedOrder),"new history page restores saved order");secondPanel.Dispose();}finally{Storage.PathName=configPath;}panel.Dispose();File.WriteAllText(Path.Combine(folder,"history-process-results.txt"),"ALL PASS: local/invalid connection feedback, no hardware collection during connection test, snapshot copy, disk reopen, chart timestamp selection, rapid selection, per-GPU filter, readonly, legacy missing, reorder edit guard, timestamp layout retention, local XML save/reload and new page order restore\n");return 0;}
}
